$('settings').onsubmit=e=>{e.preventDefault();run(async()=>{const c=config(),r=new URL(c.redirectUri);if(r.origin!==location.origin||r.pathname!==location.pathname||r.search||r.hash)throw Error('Redirect URL must exactly match this app URL, without query or fragment.');if(r.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(r.hostname))throw Error('Deploy to HTTPS before signing in.');if(!c.clientId)throw Error('REG portal sign-in setup is pending. A REG portal administrator must complete the one-time registration for this app.');const verifier=randomKey(),nonce=randomKey();sessionStorage.setItem('reg.pkce',JSON.stringify({verifier,state:nonce,config:c,time:Date.now()}));const u=new URL(c.portalUrl+'/sharing/rest/oauth2/authorize');u.search=new URLSearchParams({client_id:c.clientId,response_type:'code',redirect_uri:c.redirectUri,state:nonce,code_challenge:await challenge(verifier),code_challenge_method:'S256'});location.assign(u.href);});};
