async function callback(){const p=new URLSearchParams(location.search);if(!p.has('code')&&!p.has('error'))return;const pending=JSON.parse(sessionStorage.getItem('reg.pkce')||'null');sessionStorage.removeItem('reg.pkce');history.replaceState({},'',location.pathname);if(!pending||p.get('state')!==pending.state||Date.now()-pending.time>600000)throw Error('Sign-in state is invalid or expired. Start sign-in again.');if(p.has('error'))throw Error('Portal sign-in failed: '+p.get('error'));const c=pending.config;const response=await fetch(c.portalUrl+'/sharing/rest/oauth2/token',{method:'POST',credentials:'omit',referrerPolicy:'no-referrer',body:new URLSearchParams({f:'json',grant_type:'authorization_code',client_id:c.clientId,redirect_uri:c.redirectUri,code:p.get('code'),code_verifier:pending.verifier})});const token=await response.json();if(!response.ok||token.error||!token.access_token)throw Error('Token exchange failed. Verify app registration, PKCE support and portal CORS.');await activate(new ArcGIS(c.portalUrl,token.access_token,Date.now()+Number(token.expires_in||3600)*1000));}
