async function discover(){const items=await state.api.discover($('search').value);$('services').replaceChildren(new Option('Select a service',''));for(const item of items)if(item.url)$('services').add(new Option(item.title,item.url));status(`${items.length} accessible feature services found.`);}
$('search-form').onsubmit=e=>{e.preventDefault();run(discover);};
async function service(url){url=secureUrl(url);if(!/\/FeatureServer$/i.test(url))throw Error('Enter a FeatureServer service root URL.');const origin=new URL(url).origin;if(!state.api.allowed.has(origin)&&!confirm(`Approve sending your ArcGIS access token to ${origin}? Only approve a trusted REG GIS server.`))return;state.api.allow(url);const j=await state.api.request(url);state.serviceMeta=j;$('layers').replaceChildren(new Option('Select a layer or table',''));for(const layer of [...(j.layers||[]),...(j.tables||[])])$('layers').add(new Option(layer.name,url+'/'+layer.id));$('data').hidden=true;state.meta=null;status('Service loaded. Select a layer or table.');}
$('services').onchange=()=>{if($('services').value)run(()=>service($('services').value));};$('direct-form').onsubmit=e=>{e.preventDefault();run(()=>service($('direct').value));};
$('layers').onchange=()=>{if($('layers').value)run(async()=>{state.url=$('layers').value;state.meta={...state.serviceMeta,...await state.api.request(state.url)};if(!state.meta.fields?.length)throw Error('No field schema was returned.');const oid=state.meta.objectIdField||state.meta.fields.find(f=>f.type==='esriFieldTypeOID')?.name;if(!oid)throw Error('This layer has no supported object ID.');state.meta.objectIdField=oid;applyAttributeFilter();await prepareEditing();state.page=0;state.where='1=1';state.baseWhere='1=1';state.globalId='';$('globalid').value='';const gid=globalIdField(state.meta);$('globalid-form').hidden=!gid;text($('globalid-help'),gid?'Global ID field: '+gid.name+'. Searches all accessible matching records in this layer; the applied WHERE filter also applies.':'This layer or table does not expose a Global ID field.');text($('globalid-result'),'');$('where').value=state.where;text($('layer-title'),state.meta.name);text($('permissions'),state.meta.isDataVersioned?(state.meta.__editContext?'Versioned service: verified default version '+state.meta.__editContext.versionName+'. Enable direct editing below, then click a record.':state.meta.__versionError):'Click a record to edit supported attributes. Review and confirm to save directly to the service.');$('data').hidden=false;await loadIds();});};
async function loadIds(){state.where=globalIdWhere(state.meta,state.globalId,state.baseWhere);state.ids=await state.api.ids(state.url,state.where);state.page=0;await loadPage();}
function makeTable(headers,rows,click){const table=document.createElement('table'),head=table.createTHead().insertRow();for(const h of headers){const th=document.createElement('th');text(th,h);head.append(th);}const body=table.createTBody();rows.forEach((row,i)=>{const tr=body.insertRow();for(const value of row){const td=tr.insertCell();text(td,value);if(value==null)td.className='null';td.title=value==null?'NULL':String(value);}if(click){tr.onclick=()=>click(i);tr.tabIndex=0;tr.onkeydown=e=>{if(e.key==='Enter')click(i);};}});return table;}
async function loadPage(){const size=Math.max(1,Math.min(Number(defaults.pageSize)||100,500));state.rows=await state.api.records(state.url,state.ids.slice(state.page*size,(state.page+1)*size),state.meta);$('table').replaceChildren(makeTable(visibleFields(state.meta).map(f=>f.alias||f.name),state.rows.map(r=>visibleFields(state.meta).map(f=>{const v=r.attributes[f.name],d=domainFor(state.meta,f,r.attributes);const code=d?.codedValues?.find(c=>c.code===v);return code?`${code.name} [${v}]`:v;})),openEditor));if(!visibleFields(state.meta).length){$('table').textContent=$('attribute-profile').value?'No matching workbook attributes in this layer.':'Choose your data attribute group above to display its columns.';}const inspection=inspect({...state.meta,fields:visibleFields(state.meta)},state.rows);$('schema').replaceChildren(makeTable(['Field','Alias','Type','Nullable','Nulls (page)','Domain issues (page)'],inspection.map(r=>[r.field,r.alias,r.type,r.nullable,r.nulls,r.invalid])));text($('count'),state.ids.length);text($('null-count'),inspection.reduce((s,r)=>s+r.nulls,0));text($('invalid-count'),inspection.reduce((s,r)=>s+r.invalid,0));text($('page'),`Page ${state.ids.length?state.page+1:0} of ${Math.ceil(state.ids.length/size)} · ${state.rows.length} records`);text($('globalid-result'),state.globalId?(state.ids.length?state.ids.length+' record(s) matched '+parseGlobalIds(state.globalId).length+' requested Global ID(s). Use the bulk tools to update these matches.':'No records match these Global IDs within the applied filter.'):state.ids.length?'':'No records match the applied filter.');status($('attribute-profile').value?'Live attributes loaded for your chosen group. Inspection totals apply to this page.':'Choose a workbook attribute group to show your selected data.');}
$('filter-form').onsubmit=e=>{e.preventDefault();run(async()=>{state.baseWhere=$('where').value.trim()||'1=1';await loadIds();});};$('previous').onclick=()=>run(async()=>{if(state.page>0){state.page--;await loadPage();}});$('next').onclick=()=>run(async()=>{if((state.page+1)*Math.min(defaults.pageSize||100,500)<state.ids.length){state.page++;await loadPage();}});
function openEditor(index){state.record=structuredClone(state.rows[index].attributes);state.changes=[];text($('record-id'),state.record[state.meta.objectIdField]);$('edit-fields').replaceChildren();for(const field of visibleFields(state.meta)){const div=document.createElement('div');div.className='field';const label=document.createElement('label');text(label,field.alias||field.name);const hint=document.createElement('small'),d=domainFor(state.meta,field,state.record);const allowed=editable(field,state.meta,state.user,state.record)&&['esriFieldTypeString','esriFieldTypeSmallInteger','esriFieldTypeInteger','esriFieldTypeSingle','esriFieldTypeDouble','esriFieldTypeBigInteger','esriFieldTypeDate','esriFieldTypeGUID'].includes(field.type);text(hint,`${field.name} · ${field.type.replace('esriFieldType','')} · ${allowed?'editable':'read-only: '+(editingReason(field,state.meta,state.user,state.record)||'Unsupported field type')}${d?.type==='range'?' · range '+d.range.join(' – '):''}`);const input=d?.type==='codedValue'?document.createElement('select'):document.createElement('input');input.dataset.field=field.name;input.dataset.writable=String(allowed);input.id='field-'+field.name;label.htmlFor=input.id;input.disabled=!allowed;const old=state.record[field.name];if(input.tagName==='SELECT'){input.add(new Option('Choose a value',''));d.codedValues.forEach((c,i)=>input.add(new Option(`${c.name} [${c.code}]`,String(i))));const ix=d.codedValues.findIndex(c=>c.code===old);input.value=ix<0?'':String(ix);}else input.value=old==null?'':field.type==='esriFieldTypeDate'?new Date(old).toISOString():String(old);const nullLabel=document.createElement('label');nullLabel.className='null-toggle';const toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=old==null;toggle.dataset.null=field.name;toggle.disabled=!allowed||field.nullable===false;toggle.onchange=()=>{if(toggle.checked)input.value='';};input.placeholder=old==null&&allowed?'Enter a value to replace NULL':'';input.oninput=()=>{if(allowed)toggle.checked=false;};input.onchange=()=>{if(allowed)toggle.checked=false;};nullLabel.append(toggle,document.createTextNode('Set NULL'));div.append(label,hint,input,nullLabel);$('edit-fields').append(div);}$('editor').showModal();}
$('close-editor').onclick=()=>$('editor').close();$('back-review').onclick=()=>$('review-dialog').close();
$('edit-form').onsubmit=e=>{e.preventDefault();run(async()=>{const changes=[];for(const field of visibleFields(state.meta)){if(!editable(field,state.meta,state.user,state.record))continue;const input=[...$('edit-fields').querySelectorAll('[data-field]')].find(e=>e.dataset.field===field.name);if(!input||input.dataset.writable!=='true')continue;const toggle=[...$('edit-fields').querySelectorAll('[data-null]')].find(e=>e.dataset.null===field.name),d=domainFor(state.meta,field,state.record);let raw=input.value;if(input.tagName==='SELECT'&&raw!=='')raw=String(d.codedValues[Number(raw)].code);const old=state.record[field.name];if((toggle.checked&&old==null)||(!toggle.checked&&old!=null&&input.tagName!=='SELECT'&&raw===(old==null?'':field.type==='esriFieldTypeDate'?new Date(old).toISOString():String(old))))continue;const value=parseValue(raw,field,d,toggle.checked);if(value!==old)changes.push({field:field.name,before:old,after:value});}if(!changes.length){status('No attribute changes to review.');return;}state.changes=changes;text($('review-target'),'Target: '+state.url+(state.meta.__editContext?' · version '+state.meta.__editContext.versionName:' · published service data')+'. These are live changes.');$('changes').replaceChildren(makeTable(['Field','Current value','Proposed value'],changes.map(c=>[c.field,c.before,c.after])));$('review-dialog').showModal();});};
$('save').onclick=()=>run(async()=>{const meta={...state.serviceMeta,...await state.api.request(state.url),__editContext:state.meta.__editContext,__editEnabled:state.meta.__editEnabled,__allowedFields:state.meta.__allowedFields},id=state.record[state.meta.objectIdField],fresh=(await state.api.records(state.url,[id],state.meta))[0].attributes;if(state.meta.typeIdField&&fresh[state.meta.typeIdField]!==state.record[state.meta.typeIdField])throw Error('Record subtype changed. Reload and review again.');for(const c of state.changes){const field=meta.fields.find(f=>f.name===c.field);if(!field||!editable(field,meta,state.user,fresh))throw Error('Editing permission or schema changed. Reopen the record.');if(fresh[c.field]!==c.before)throw Error(`The server value for ${c.field} changed. Reload and review again.`);parseValue(c.after==null?'':field.type==='esriFieldTypeDate'?new Date(c.after).toISOString():String(c.after),field,domainFor(meta,field,fresh),c.after==null);}const attrs={[state.meta.objectIdField]:id};state.changes.forEach(c=>attrs[c.field]=c.after);if(meta.isDataVersioned){const current=verifiedDefault(await state.api.request(state.url.replace(/\/FeatureServer\/\d+$/i,'/VersionManagementServer'),{},'GET'));if(current.versionName!==meta.__editContext.versionName||current.versionGuid!==meta.__editContext.versionGuid)throw Error('The default version changed. Reselect the layer and review again.');}const result=await state.api.request(state.url+'/applyEdits',{updates:JSON.stringify([{attributes:attrs}]),rollbackOnFailure:true,...versionParameters(meta)});const r=result.updateResults?.[0];if(!r?.success)throw Error(r?.error?.description||'The server rejected this update.');$('review-dialog').close();$('editor').close();await loadPage();status(`Record ${id} saved successfully. Server accepted ${state.changes.length} field change(s).`);});
$('export').onclick=()=>run(async()=>{const rows=await state.api.all(state.url,state.meta,state.where,(n,total)=>status(`Exporting ${n.toLocaleString()} / ${total.toLocaleString()} records…`));const schema=visibleFields(state.meta);if(!schema.length)throw Error('No workbook attributes match this layer. Select another template group before exporting.');const inspection=inspect({...state.meta,fields:schema},rows);const sheets=[];const chunk=1048575;for(let i=0;i<Math.max(rows.length,1);i+=chunk)sheets.push({name:'Attributes '+(Math.floor(i/chunk)+1),rows:[schema.map(f=>f.name),...rows.slice(i,i+chunk).map(r=>schema.map(f=>r.attributes[f.name]))]});sheets.push({name:'Schema',rows:[['Field','Alias','Type','Nullable','Length','Domain JSON'],...schema.map(f=>[f.name,f.alias,f.type,f.nullable!==false,f.length,JSON.stringify(f.domain||null)])]},{name:'Subtypes',rows:[['Subtype metadata JSON'],[JSON.stringify((state.meta.types||[]).map(type=>({id:type.id,name:type.name,domains:Object.fromEntries(Object.entries(type.domains||{}).filter(([name])=>schema.some(field=>field.name===name)))})))]]},{name:'Inspection',rows:[['Field','Null count','Domain issues'],...inspection.map(r=>[r.field,r.nulls,r.invalid])]},{name:'Export info',rows:[['Property','Value'],['Service',state.url],['Version',state.meta.__editContext?.versionName||'Published service version'],['Filter',state.where],['Exported UTC',new Date().toISOString()],['Records',rows.length],['Dates','ArcGIS date values are UTC epoch milliseconds. Nulls are blank; strings remain literal text.'],['Consistency','IDs captured at export start. Concurrent server edits may affect values. Missing records abort export.']]});const blob=workbook(sheets),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='REG-attributes-'+new Date().toISOString().slice(0,10)+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status(`Export complete: ${rows.length.toLocaleString()} records across all pages.`);});
run(callback);






$('globalid-form').onsubmit=e=>{e.preventDefault();run(async()=>{const value=$('globalid').value.trim();if(!value)throw Error('Paste a Global ID to search.');globalIdWhere(state.meta,value,state.baseWhere);state.globalId=value;await loadIds();});};
$('clear-globalid').onclick=()=>run(async()=>{state.globalId='';$('globalid').value='';await loadIds();});


async function prepareEditing(){
 const meta=state.meta,root=state.url.replace(/\/\d+$/,'');state.api.versions.delete(root);$('editing-mode').hidden=!meta.isDataVersioned;$('enable-direct-edit').checked=false;meta.__editEnabled=false;
 if(!meta.isDataVersioned)return;
 try{meta.__editContext=verifiedDefault(await state.api.request(root.replace(/\/FeatureServer$/i,'/VersionManagementServer'),{},'GET'));state.api.versions.set(root,meta.__editContext.versionName);text($('editing-target'),'Live editing target: '+meta.__editContext.versionName+' (default version verified by the service).');}
 catch(error){meta.__versionError='Direct editing is unavailable: '+error.message;text($('editing-target'),meta.__versionError);}
}
$('enable-direct-edit').onchange=()=>{if(!state.meta?.__editContext){$('enable-direct-edit').checked=false;return;}state.meta.__editEnabled=$('enable-direct-edit').checked;status(state.meta.__editEnabled?'Direct editing enabled for '+state.meta.__editContext.versionName+'. Click a record, change permitted attributes, review, then save.':'Direct editing disabled.');};


attachBulk({state,$,run,status,makeTable,loadIds});
attachSurveyMonitor({state,$,makeTable});

$('attribute-profile').add(new Option('Choose the data attributes to show…',''));
for(const profile of attributeProfiles.profiles)$('attribute-profile').add(new Option(profile.label,profile.id));
function applyAttributeFilter(){
 const profile=attributeProfiles.profiles.find(p=>p.id===$('attribute-profile').value)||{label:'No group selected',attributes:[]};
 const result=matchAttributes(state.meta,profile);state.meta.__allowedFields=result.fields.map(field=>field.name);state.meta.__attributeProfile=profile.label;
 text($('attribute-summary'),!$('attribute-profile').value?'Choose a group above. Only attributes from your chosen group will be visible.':result.fields.length+' workbook attribute(s) shown for '+profile.label+'. '+(state.meta.fields.length-result.fields.length)+' other service field(s) hidden.');
 text($('attribute-unmatched'),!$('attribute-profile').value?'Choose an attribute group first.':result.unmatched.length?result.unmatched.join(' · '):'All headings in this group match fields in the selected layer.');
}
$('attribute-profile').onchange=()=>run(async()=>{if(!state.meta)return;applyAttributeFilter();await loadPage();if($('attribute-profile').value&&!visibleFields(state.meta).length)status('No fields in this layer match the selected workbook group. Choose the relevant group; missing fields are not created.');});

